        stack = [u]
        visited = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if node == v:
                return True
            for neighbor in graph[node]:
                if neighbor != parent and (mask >> (neighbor - 1)) & 1:
                    stack.append(neighbor)
        return False

    valid_masks = []
